async function probe(file,url,type){if(type==='image'){return new Promise(resolve=>{const img=new Image();img.onload=()=>resolve({duration:15,width:img.naturalWidth,height:img.naturalHeight});img.onerror=()=>resolve({duration:15});img.src=url})}return new Promise(resolve=>{const m=document.createElement(type==='audio'?'audio':'video');m.preload='metadata';let settled=false;const done=()=>{if(settled)return;settled=true;resolve({duration:Number.isFinite(m.duration)?m.duration:0,width:m.videoWidth||0,height:m.videoHeight||0});m.removeAttribute('src');m.load()};m.onloadedmetadata=done;m.onerror=done;setTimeout(done,9000);m.src=url})}
async function addFile(file){const existing=p.assets.find(a=>a.name===file.name&&a.size===file.size);if(existing){const prev=assets.get(existing.id);if(prev?.url)URL.revokeObjectURL(prev.url);const url=URL.createObjectURL(file);Object.assign(existing,{url});assets.set(existing.id,{...existing,file,url});if(p.settings.rememberMedia)saveMedia(existing.id,file).catch(()=>{});return existing}
const type=file.type.startsWith('video')||/\.(mkv|mp4|mov|avi|webm)$/i.test(file.name)?'video':file.type.startsWith('image')?'image':'audio',id=uid(),url=URL.createObjectURL(file),info=await probe(file,url,type),data={id,name:file.name,type,mime:file.type||'',size:file.size,lastModified:file.lastModified,duration:info.duration|| (type==='image'?15:0),width:info.width||0,height:info.height||0,url};p.assets.push(data);assets.set(id,{...data,file});p.selectedAsset=id;if(p.settings.rememberMedia)saveMedia(id,file).catch(e=>toast(`Media cache not saved: ${e.message}`,true));return data}
async function importFiles(files){const array=[...files].filter(x=>x.type.startsWith('video/')||x.type.startsWith('audio/')||x.type.startsWith('image/')||/\.(mkv|mov|mp4|webm|wav|mp3|m4a)$/i.test(x.name));if(!array.length)return toast('No supported media files selected',true);commit();for(const file of array){try{await addFile(file)}catch(e){toast(`Import ${file.name}: ${e.message}`,true)}}update();toast(`Imported / relinked ${array.length} media file(s)`)}
async function restore(){try{const saved=await loadProject();if(saved){p=validateProject(saved);for(const a of p.assets){try{const file=await loadMedia(a.id);if(file){const url=URL.createObjectURL(file);a.url=url;assets.set(a.id,{...a,file,url})}}catch{}}}}catch(e){console.warn('Restore',e.message)}draw()}
function openJSON(file){file.text().then(text=>{try{const newp=validateProject(JSON.parse(text));engine.pause();history=[];future=[];assets.forEach(a=>a.url&&URL.revokeObjectURL(a.url));assets.clear();p=newp;draw();toast('Project loaded. Import original media to relink by filename and file size.')}catch(e){toast(`Could not open project: ${e.message}`,true)}})}
function bind(){all('.tab').forEach(b=>b.onclick=()=>chooseTab(b.dataset.tab));$('projectName').onchange=e=>{commit();p.name=e.target.value||'Untitled Project';setStatus('Renamed')};$('newProject').onclick=()=>{if(!confirm('Create a new project? Save/export your current project first.'))return;engine.pause();history=[];future=[];p=newProject();assets.forEach(a=>a.url&&URL.revokeObjectURL(a.url));assets.clear();draw()};$('saveProject').onclick=()=>save();$('exportProject').onclick=()=>download(JSON.stringify({...p,assets:p.assets.map(({file,url,...rest})=>rest)},null,2),`${p.name}-project.json`,'application/json');$('loadProject').onchange=e=>e.target.files[0]&&openJSON(e.target.files[0]);$('goExport').onclick=()=>chooseTab('export');$('fileUpload').onchange=e=>{importFiles(e.target.files);e.target.value=''};$('dropzone').onclick=()=>$('fileUpload').click();$('dropzone').onkeydown=e=>{if(e.key==='Enter')$('fileUpload').click()};for(const e of ['dragover','dragenter'])$('dropzone').addEventListener(e,x=>{x.preventDefault();$('dropzone').classList.add('dragover')});$('dropzone').ondragleave=()=>$('dropzone').classList.remove('dragover');$('dropzone').ondrop=e=>{e.preventDefault();$('dropzone').classList.remove('dragover');importFiles(e.dataTransfer.files)};$('addSelection').onclick=()=>{const a=asset(p.selectedAsset);if(!a)return toast('Select a source',true);if(!a.duration)return toast('Cannot determine source duration. This codec may not be playable in the browser.',true);const st=clamp($('sourceIn').value,0,a.duration-.1),end=clamp($('sourceOut').value,st+.1,a.duration);if(end<=st)return toast('Set a valid source time range',true);commit();const seg=makeSegment(a.id,st,end);seg.transition=p.settings.transition;p.segments.push(seg);p.selectedSegment=seg.id;update();toast(`Added ${fmt(end-st)} from ${a.name}`)};$('aspectSelect').onchange=e=>{commit();p.settings.aspect=e.target.value;engine.setSize();update()};$('toggleCaptions').onclick=()=>{commit();p.settings.captionOn=!p.settings.captionOn;update()};$('playButton').onclick=async()=>{await engine.play();engine.onTick(engine.time)};$('skipBack').onclick=()=>engine.seek(engine.time-5);$('skipForward').onclick=()=>engine.seek(engine.time+5);$('playhead').oninput=e=>engine.seek(Number(e.target.value));$('mutePreview').onclick=()=>{engine.previewMuted=!engine.previewMuted;$('mutePreview').textContent=engine.previewMuted?'♪̸':'♫';engine.syncAudio()};$('undoBtn').onclick=undo;$('redoBtn').onclick=redo;$('splitBtn').onclick=splitSelected;$('deleteBtn').onclick=removeSelected;$('fitBtn').onclick=()=>engine.seek(0);window.addEventListener('keydown',e=>{const focus=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'');if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(focus)return;if(e.key===' '){e.preventDefault();engine.play()}else if(e.key==='ArrowLeft'){e.preventDefault();engine.seek(engine.time-5)}else if(e.key==='ArrowRight'){e.preventDefault();engine.seek(engine.time+5)}else if(e.key==='Delete'||e.key==='Backspace')removeSelected();else if(e.ctrlKey&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo()}});window.addEventListener('beforeunload',()=>{clearTimeout(saving)})}
bind();restore();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
